import functools
@functools.lru_cache(None)
def f(a, b):
    if a * b == 1: return 0
    return 1 + min([f(i, b) + f(a - i, b) for i in range(1, a)] + [f(a, j) + f(a, b - j) for j in range(1, b)])
result = f(3, 4)

def sw(s): return [s[:i] + (s[i + 1], s[i]) + s[i + 2:] for i in range(len(s) - 1)]
seen = {(4, 1, 3, 2): 0}; todo = [(4, 1, 3, 2)]
for s in todo:
    for t in sw(s):
        if t not in seen: seen[t] = seen[s] + 1; todo.append(t)
result = seen[(1, 2, 3, 4)]

